import os, json, yaml, pandas as pd, numpy as np, matplotlib.pyplot as plt, plot_style, sys
sys.path.append(os.path.join(os.path.dirname(__file__), '..'))
from analysis import analyze_results
def generate_all():
    plot_style.apply(); analyze_results()
    with open("config.yaml", "r") as f: config = yaml.safe_load(f)
    with open("outputs/manifest.json", "r") as f: manifest = json.load(f)
    with open("outputs/results.json", "r") as f: results = json.load(f)
    st, ts, pols = results['stats'], results['tests'], results['policies']
    sm_man = {}
    def reg(fn, sd): sm_man[fn] = sd
    pd.DataFrame([{'Policy': p, 'SKR_Mean': st[p]['skr_mean'], 'SKR_CI_Low': st[p]['skr_ci_low'], 'SKR_CI_High': st[p]['skr_ci_high'], 'T2K_Mean': st[p]['t2k_mean'], 'T2K_CI_Low': st[p]['t2k_ci_low'], 'T2K_CI_High': st[p]['t2k_ci_high']} for p in pols]).to_csv("src/outputs/tables/tradeoff_comparison.csv", index=False); reg("tables/tradeoff_comparison.csv", "results.json")
    pd.DataFrame([{'Policy': p, 'Availability_Percent': st[p]['availability_percent'], 'Failure_Rate_Percent': st[p]['failure_rate_percent']} for p in pols]).to_csv("src/outputs/tables/key_availability_summary.csv", index=False); reg("tables/key_availability_summary.csv", "results.json")
    pd.DataFrame([{'Comparison': 'DBS vs Fixed Large', 'Statistic': ts['dbs_vs_large']['statistic'], 'P_Value': ts['dbs_vs_large']['p_value'], 'Effect_Size_Cohens_D': ts['dbs_vs_large']['effect_size_cohens_d']}, {'Comparison': 'DBS vs Fixed Small', 'Statistic': ts['dbs_vs_small']['statistic'], 'P_Value': ts['dbs_vs_small']['p_value'], 'Effect_Size_Cohens_D': ts['dbs_vs_small']['effect_size_cohens_d']}]).to_csv("src/outputs/tables/wilcoxon_test_results.csv", index=False); reg("tables/wilcoxon_test_results.csv", "results.json")
    pd.DataFrame([{'Constant': k, 'Value': v, 'Source_Citation': 'Brassard and Salvail (1993)' if k=='error_correction_efficiency_f' else 'Project Specs'} for k,v in config.items()]).to_csv("src/outputs/tables/config_constants_used.csv", index=False); reg("tables/config_constants_used.csv", "config.yaml")
    pd.DataFrame([manifest]).to_csv("src/outputs/tables/rtt_source_manifest.csv", index=False); reg("tables/rtt_source_manifest.csv", "outputs/manifest.json")
    qa = np.array(results['qber_series']); pd.DataFrame([{'Min': np.min(qa), 'Max': np.max(qa), 'Mean': np.mean(qa), 'Std': np.std(qa)}]).to_csv("src/outputs/tables/qber_summary_stats.csv", index=False); reg("tables/qber_summary_stats.csv", "results.json")
    db = results['data']['dbs']['block_sizes']; lc, sc = db.count(config['block_size_low_latency_bits']), db.count(config['block_size_high_latency_bits']); pd.DataFrame([{'Block_Size': config['block_size_low_latency_bits'], 'Count': lc, 'Percent': (lc/len(db))*100}, {'Block_Size': config['block_size_high_latency_bits'], 'Count': sc, 'Percent': (sc/len(db))*100}]).to_csv("src/outputs/tables/block_size_selection_summary.csv", index=False); reg("tables/block_size_selection_summary.csv", "results.json")
    pd.DataFrame([{'Policy': p, 'Failed_Blocks': results['data'][p]['failed_blocks'], 'Percent': (results['data'][p]['failed_blocks']/len(results['rtt_series']))*100} for p in pols]).to_csv("src/outputs/tables/key_generation_failure_summary.csv", index=False); reg("tables/key_generation_failure_summary.csv", "results.json")
    pd.DataFrame([{"Status": "Pending", "Details": "Check reproducibility_diff.txt"}]).to_csv("src/outputs/tables/reproducibility_diff_summary.csv", index=False); reg("tables/reproducibility_diff_summary.csv", "Placeholder")
    pd.DataFrame([{'Policy': p, 'p5': np.percentile(results['data'][p]['skr'], 5), 'p25': np.percentile(results['data'][p]['skr'], 25), 'Median': np.median(results['data'][p]['skr']), 'p75': np.percentile(results['data'][p]['skr'], 75), 'p95': np.percentile(results['data'][p]['skr'], 95)} for p in pols]).to_csv("src/outputs/tables/skr_percentiles_by_policy.csv", index=False); reg("tables/skr_percentiles_by_policy.csv", "results.json")
    plt.figure(figsize=(10,4)); plt.plot(results['rtt_series'], color=plot_style.STYLE['primary']); plt.axhline(config['rtt_threshold_ms'], color=plot_style.STYLE['secondary'], linestyle='--'); plt.savefig("src/outputs/figures/latency_trend.png"); plt.close(); reg("figures/latency_trend.png", "results.json")
    plt.figure(figsize=(8,6)); [plt.errorbar(st[p]['skr_mean'], st[p]['t2k_mean'], xerr=st[p]['skr_mean']-st[p]['skr_ci_low'], yerr=st[p]['t2k_mean']-st[p]['t2k_ci_low'], fmt='o') for p in pols]; plt.savefig("src/outputs/figures/tradeoff_comparison.png"); plt.close(); reg("figures/tradeoff_comparison.png", "results.json")
    plt.figure(figsize=(8,6)); plt.violinplot([results['data'][p]['skr'] for p in pols], showmeans=True); plt.xticks([1,2,3], pols); plt.savefig("src/outputs/figures/skr_distribution_by_policy.png"); plt.close(); reg("figures/skr_distribution_by_policy.png", "results.json")
    plt.figure(figsize=(8,6)); plt.bar(pols, [st[p]['availability_percent'] for p in pols]); plt.savefig("src/outputs/figures/key_availability_percent_by_policy.png"); plt.close(); reg("figures/key_availability_percent_by_policy.png", "results.json")
    plt.figure(figsize=(8,6)); plt.boxplot([results['data'][p]['t2k'] for p in pols], tick_labels=pols); plt.savefig("src/outputs/figures/t2k_distribution_by_policy.png"); plt.close(); reg("figures/t2k_distribution_by_policy.png", "results.json")
    plt.figure(figsize=(10,4)); plt.step(range(len(db)), db, where='post'); plt.savefig("src/outputs/figures/block_size_selection_over_time.png"); plt.close(); reg("figures/block_size_selection_over_time.png", "results.json")
    plt.figure(figsize=(8,6)); plt.hist(results['qber_series'], bins=30); plt.savefig("src/outputs/figures/qber_distribution.png"); plt.close(); reg("figures/qber_distribution.png", "results.json")
    plt.figure(figsize=(8,6)); plt.bar(pols, [st[p]['failure_rate_percent'] for p in pols]); plt.savefig("src/outputs/figures/key_generation_failure_rate_by_policy.png"); plt.close(); reg("figures/key_generation_failure_rate_by_policy.png", "results.json")
    plt.figure(figsize=(8,6)); plt.bar(['DBS vs Fixed Large', 'DBS vs Fixed Small'], [ts['dbs_vs_large']['effect_size_cohens_d'], ts['dbs_vs_small']['effect_size_cohens_d']]); plt.savefig("src/outputs/figures/wilcoxon_effect_size_comparison.png"); plt.close(); reg("figures/wilcoxon_effect_size_comparison.png", "results.json")
    plt.figure(figsize=(8,6)); plt.scatter(results['rtt_series'], results['data']['dbs']['skr']); plt.scatter(results['rtt_series'], results['data']['fixed_large']['skr']); plt.savefig("src/outputs/figures/skr_vs_rtt_scatter.png"); plt.close(); reg("figures/skr_vs_rtt_scatter.png", "results.json")
    with open("src/outputs/source_manifest.json", "w") as f: json.dump(sm_man, f, indent=4)
if __name__ == "__main__": generate_all()
